import { z } from "zod"

/**
 * r29b: the name the game registers a creature or a book by, the part after `<mod id>:` (`shanhai:xingtian`), written the way a block's or an
 * item's `identifier` is. Optional, and absent in every older project: then the name is made of the thing's id (`creature_<hex>`, `book_<hex>`),
 * which is what every build named it before, so such a project is generated byte for byte as before. Its spawn egg, language keys, loot table,
 * model files and a boss's lair all follow it. No Node APIs: the window's own words read it.
 */
export const RegistryNameSchema = z
  .string()
  .trim()
  .regex(/^[a-z][a-z0-9_]{0,63}$/, "注册名（identifier）只能用小写字母、数字和下划线，小写字母开头，最多 64 个字，不带模组前缀：写 xingtian，不写 shanhai:xingtian。")
  .refine((name) => !/^(creature|book)_[0-9a-f]{32}$/.test(name), "creature_ 或 book_ 加 32 位编号是 Studio 自动起的名字，自己起名换一个，或者不写 identifier。")

/** For whoever writes a creature or a book document: short, as the creature's request is near its limit. */
export const REGISTRY_NAME_INSTRUCTIONS = {
  creature: " 可选 identifier：生物的注册名（不带模组前缀，例如 xingtian），刷怪蛋、/summon、巢的名字都跟着它；不写是 creature_ 加编号。用户点了名才写；打过包的生物改了它，旧世界里的那只会消失。",
  book: " 可选 identifier：书的注册名（不带模组前缀，例如 canjuan）；不写是 book_ 加编号。用户点了名才写；改了它，旧世界里的这本书会消失。",
} as const

const hex = (id: string) => id.replaceAll("-", "")

/** A creature's registry name: its `identifier`, or `creature_<its id without dashes>` as before. Its id is its model's. */
export const creatureName = (creature: { id: string; identifier?: string | null | undefined }) => creature.identifier || `creature_${hex(creature.id)}`
/** The registry name of the creature of the project with this id (a creature not in the project: the name its id makes). */
export const creatureNameOf = (project: { entities: readonly { id: string; identifier?: string | null | undefined }[] }, id: string) => creatureName(project.entities.find((entity) => entity.id === id) ?? { id })
/** A book's registry name: the item, its language keys and the tags a player carries for it. Its `identifier`, or `book_<its asset id without dashes>` as before. */
export const bookName = (book: { id: string; document: { identifier?: string | null | undefined } }) => book.document.identifier || `book_${hex(book.id)}`

/**
 * The entity types every mod of Studio may register besides its creatures (`PROJECTILE_RUNTIME`, `GROUND_FX_RUNTIME`, the arena's fixture,
 * `BOSS_LOOK_RUNTIME`, `EFFECT_RUNTIME`, `PART_RUNTIME` and the terrain pieces); `registry-name.test.ts` holds them to those classes' own names.
 */
export const RESERVED_ENTITY_NAMES = ["studio_projectile", "studio_fx", "studio_fixture", "boss_part", "studio_effect", "studio_part", "studio_terrain"] as const

type Named = { kind: "entity" | "book"; id: string; name: string; registry: string }
export type RegistryClash = Named & { other: Owner }
type Owner = { id: string | null; words: string; name: string }

type Source = {
  mod_id: string
  entities: readonly { id: string; name: string; identifier?: string | null | undefined }[]
  items: readonly { id: string; name: string; identifier: string }[]
  blocks: readonly { id: string; name: string; identifier: string }[]
  workspace: { assets: readonly { id: string; title: string; document: { kind: string } }[] }
}

const booksOf = (project: Source) =>
  project.workspace.assets.flatMap((asset) => (asset.document.kind === "book" ? [{ id: asset.id, title: asset.title, document: asset.document as { kind: "book"; name: string; identifier?: string | null } }] : []))

/**
 * Every creature and book whose own `identifier` takes a name the game already gives something else of the mod. Two registries count: the
 * creatures' (each other's names and the entity types every mod has) and the items' (items, blocks, books and every creature's `<name>_spawn_egg`).
 * A creature and an item may share a name, as the game lets them. Only a thing that writes `identifier` is checked: a project without any has no clash.
 */
export function registryClashes(project: Source): RegistryClash[] {
  const books = booksOf(project)
  const creatures = project.entities.map((entity) => ({ id: entity.id, name: entity.name, registry: creatureName(entity), own: Boolean(entity.identifier) }))
  const entityNames = new Map<string, Owner[]>()
  const itemNames = new Map<string, Owner[]>()
  const put = (into: Map<string, Owner[]>, name: string, owner: Owner) => into.set(name, [...(into.get(name) ?? []), owner])
  RESERVED_ENTITY_NAMES.forEach((name) => put(entityNames, name, { id: null, words: "Studio 自己的一个内部生物", name }))
  creatures.forEach((creature) => {
    put(entityNames, creature.registry, { id: creature.id, words: `生物「${creature.name}」`, name: creature.registry })
    put(itemNames, `${creature.registry}_spawn_egg`, { id: creature.id, words: `生物「${creature.name}」的刷怪蛋`, name: `${creature.registry}_spawn_egg` })
  })
  project.items.forEach((item) => put(itemNames, item.identifier, { id: item.id, words: `物品「${item.name}」`, name: item.identifier }))
  project.blocks.forEach((block) => put(itemNames, block.identifier, { id: block.id, words: `方块「${block.name}」`, name: block.identifier }))
  books.forEach((book) => put(itemNames, bookName(book), { id: book.id, words: `书「${book.document.name}」`, name: bookName(book) }))
  const others = (from: Map<string, Owner[]>, name: string, self: string) => (from.get(name) ?? []).filter((owner) => owner.id !== self)
  return [
    ...creatures.filter((creature) => creature.own).flatMap((creature): RegistryClash[] => {
      const named: Named = { kind: "entity", id: creature.id, name: creature.name, registry: creature.registry }
      return [...others(entityNames, creature.registry, creature.id), ...others(itemNames, `${creature.registry}_spawn_egg`, creature.id)].slice(0, 1).map((other) => ({ ...named, other }))
    }),
    ...books.filter((book) => book.document.identifier).flatMap((book): RegistryClash[] => {
      const named: Named = { kind: "book", id: book.id, name: book.document.name, registry: bookName(book) }
      return others(itemNames, named.registry, book.id).slice(0, 1).map((other) => ({ ...named, other }))
    }),
  ]
}

/** A clash in words: what took the name, and how to change it. */
export const registryClashWords = (mod: string, clash: RegistryClash) => ({
  text: `${clash.kind === "entity" ? "生物" : "书"}「${clash.name}」的注册名写成 ${mod}:${clash.registry}${clash.other.name === clash.registry ? "" : `，它的刷怪蛋就叫 ${mod}:${clash.other.name}`}，这个名字已经${clash.other.id === null ? "是" : "给了"}${clash.other.words}：游戏里一个名字只能给一样东西，模组会装不上。`,
  // r29c: the example as the game will call it, which the person's own words keep (`creatorWords`); identifier takes the part after the colon.
  fix: `给「${clash.name}」的 identifier 换一个没人用的名字（比如改成 ${mod}:${clash.registry}_2，identifier 里只写冒号后面那段），或者删掉 identifier，用 Studio 自动起的名字。`,
})

/** Every creature and book that names itself, with the name the game knew it by before it did: old worlds lose the one of that old name. */
export function registryRenames(project: Source) {
  return [
    ...project.entities.filter((entity) => entity.identifier).map((entity) => ({ kind: "entity" as const, id: entity.id, name: entity.name, registry: creatureName(entity), before: creatureName({ id: entity.id }) })),
    ...booksOf(project).filter((book) => book.document.identifier).map((book) => ({ kind: "book" as const, id: book.id, name: book.document.name, registry: bookName(book), before: bookName({ id: book.id, document: {} }) })),
  ].filter((row) => row.registry !== row.before)
}
